structure.mermaidSource:
flowchart TD
  start_nom["Início: Identificar a expressão especial na oração"] --> dec_expr{"Qual expressão está sob análise?"}
  dec_expr -- "é proibido / bom / necessário" --> dec_det{"Há artigo 'a' ou determinante antes do substantivo?"}
  dec_det -- "Sim" --> res_det_sim["Flexione no feminino: 'é proibida a...', 'é boa a...'"]
  dec_det -- "Não" --> res_det_nao["Mantenha no masculino singular invariável: 'é proibido...'"]
  dec_expr -- "anexo / em anexo" --> dec_prep_anexo{"Está acompanhado da preposição 'em' ('em anexo')?"}
  dec_prep_anexo -- "Sim" --> res_em_anexo["Permanece invariável: 'em anexo as planilhas'"]
  dec_prep_anexo -- "Não" --> res_anexo_adj["Adjetivo: flexione com o substantivo ('anexos os autos', 'anexas as fichas')"]
  dec_expr -- "mesmo / próprio" --> dec_sent_mesmo{"Equivale a 'em pessoa' (reforço de sujeito)?"}
  dec_sent_mesmo -- "Sim" --> res_mesmo_flex["Flexione com o termo: 'elas mesmas', 'eles próprios'"]
  dec_sent_mesmo -- "Não" --> res_mesmo_invar["Advérbio invariável (sentido de 'realmente' ou 'mesmo assim')"]
  dec_expr -- "quite" --> dec_quite_num{"O sujeito/referente está no plural?"}
  dec_quite_num -- "Sim" --> res_quite_plur["Flexione no plural: 'quites' ('Estamos quites')"]
  dec_quite_num -- "Não" --> res_quite_sing["Mantenha no singular: 'quite' ('Estou quite')"]

